#!/usr/bin/env node
// Reusable markdown -> PDF renderer for the docs/audits/ study documents.
// Replaces the throwaway per-doc converters that used to live in a scratch dir:
// because those were never committed, a doc's PDF could only be regenerated by
// whoever still had the script, so the .md drifted ahead of its PDF (and the
// public/ download drifted ahead of the docs/audits/ canonical). One committed
// renderer makes every audit PDF reproducible from its .md source of truth.
//
// Usage:
//   node scripts/render-audit-doc.mjs --input docs/audits/foo.md --output docs/audits/foo.pdf
//   node scripts/render-audit-doc.mjs -i foo.md -o foo.pdf --keep-html   (debug: leave the intermediate .html)
//
// The .md is the source of truth. Tables are colour-coded on their "% saved"
// columns only (header ends with "%"): green for >=+10%, red for <=-10%, neutral
// within +/-10% so noisy N=1 cells aren't over-sold. Columns headed anything else
// (Swing/pp deltas, token counts, "Agg. (skill vs cold)") are deliberately left
// neutral — different/none savings polarity, so colour would mislead.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { printHtmlToPdf } from './lib/chrome-pdf.mjs';

function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--input' || a === '-i') out.input = argv[++i];
    else if (a === '--output' || a === '-o') out.output = argv[++i];
    else if (a === '--keep-html') out.keepHtml = true;
    else if (a === '--help' || a === '-h') out.help = true;
  }
  return out;
}

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// GitHub-style heading slug: lowercase, drop punctuation except spaces/hyphens,
// spaces -> hyphens. Matches the in-doc anchor links like (#pin-the-before-arm).
export function slug(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

export function inline(text) {
  let t = esc(text);
  const codes = [];
  t = t.replace(/`([^`]+)`/g, (_, c) => ` C${codes.push(c) - 1} `);
  t = t.replace(/\\\*/g, ' STAR ');
  // Bold first, non-greedy, allowing a nested *italic* inside (e.g. "**a *b* c**"):
  // [\s\S]+? lets the bold run span inner single-* spans, which are then resolved
  // by the italic pass on the captured content. A plain [^*]+ here would stop at the
  // first inner '*' and leave the surrounding bold unparsed with stray literal '*'.
  t = t.replace(/\*\*([\s\S]+?)\*\*/g, (_, inner) => '<strong>' + inner.replace(/\*([^*]+)\*/g, '<em>$1</em>') + '</strong>');
  t = t.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  t = t.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  t = t.replace(/ STAR /g, '*');
  t = t.replace(/ C(\d+) /g, (_, i) => `<code>${codes[+i]}</code>`);
  return t;
}

// Colour a "% saved" cell by sign + signal threshold. Gated on the column HEADER
// ending in "%" so only savings columns get coloured. Strip bold (**) but keep a
// lone footnote * so flagged cells (e.g. a contaminated "-74%*") fall through to
// neutral. Returns '' for no class.
//
// Threshold is ±20%, NOT ±10% — set to the noise floor the doc itself demonstrates.
// The Spacepotatis accidental re-measure showed ~8pp of pure cross-session drift
// (run-1 A vs run-2 B), and that band applies to every cell whose A and B arms
// weren't simultaneous (i.e. all of them) plus N=1 task-work variance on top. So
// anything inside ±20% is direction-at-best, not a magnitude we can colour as
// signal; only cells that clear the demonstrated floor get green/red.
const NOISE_FLOOR_PCT = 20;
export function pctClass(raw, header) {
  if (!(header || '').trim().endsWith('%')) return '';
  // Optional sign: a bare "38%" in a "% saved" column is a +38% save (the results
  // sheet writes saves unsigned), so unsigned and "+" read as positive; only an
  // explicit minus (− or -) is negative. The header gate keeps this scoped to
  // savings columns, where unsigned-means-positive holds across the doc family.
  const m = raw.replace(/\*\*/g, '').trim().match(/^([+−-]?)\s?(\d+)%$/);
  if (!m) return '';
  const val = (m[1] === '−' || m[1] === '-' ? -1 : 1) * parseInt(m[2], 10);
  if (val >= NOISE_FLOOR_PCT) return ' class="pos"';
  if (val <= -NOISE_FLOOR_PCT) return ' class="neg"';
  return '';
}

const state = { coloured: false };

function renderTable(lines) {
  const split = (l) => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
  const header = split(lines[0]);
  const aligns = split(lines[1]).map((c) => {
    const l = c.startsWith(':');
    const r = c.endsWith(':');
    return r && !l ? 'right' : l && r ? 'center' : 'left';
  });
  const body = lines.slice(2).map(split);
  const th = header.map((c, i) => `<th style="text-align:${aligns[i] || 'left'}">${inline(c)}</th>`).join('');
  const rows = body
    .map(
      (r) =>
        '<tr>' +
        r
          .map((c, i) => {
            const cls = pctClass(c, header[i]);
            if (cls) state.coloured = true;
            return `<td style="text-align:${aligns[i] || 'left'}"${cls}>${inline(c)}</td>`;
          })
          .join('') +
        '</tr>',
    )
    .join('\n');
  return `<table><thead><tr>${th}</tr></thead><tbody>\n${rows}\n</tbody></table>`;
}

function mdToBlocks(md) {
  return md
    .split(/\n\s*\n/)
    .map((b) => b.split('\n').filter((l) => l.trim() !== ''))
    .filter((b) => b.length);
}

// A table whose caption paragraph is bolded "**Figure N — …**" is rendered as a
// horizontal bar chart instead of a grid. The measurement reports lean on a
// couple of at-a-glance comparisons (cost as delegated vs at orchestrator
// rates, outcome counts), and a three-row table states those numbers without
// showing the ratio that is the whole point of them.
const FIGURE_CAPTION = /^\*\*Figure\s+\d+\s*[—-]\s*(.+?)\*\*$/i;

/** First cell that parses as a number, ignoring $, %, commas and spaces. */
function firstNumber(cells) {
  for (let i = 1; i < cells.length; i++) {
    const n = Number(String(cells[i]).replace(/[$,%\s]/g, ''));
    if (Number.isFinite(n) && String(cells[i]).trim() !== '') return { value: n, label: cells[i] };
  }
  return null;
}

function renderFigure(caption, tableBlock) {
  const split = (line) => line.replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
  const rows = tableBlock.slice(2).map(split);
  const bars = rows
    .map((cells) => ({ name: cells[0] ?? '', num: firstNumber(cells) }))
    .filter((r) => r.num !== null);
  if (bars.length === 0) return `<p class="figure-caption">${inline(caption)}</p>${renderTable(tableBlock)}`;
  const max = Math.max(...bars.map((b) => b.num.value));
  const items = bars
    .map((b) => {
      const pct = max > 0 ? Math.max(1.5, (b.num.value / max) * 100) : 1.5;
      return `<div class="figure-row"><div class="figure-label">${inline(b.name)}</div>` +
        `<div class="figure-track"><div class="figure-bar" style="width:${pct.toFixed(1)}%"></div></div>` +
        `<div class="figure-value">${inline(b.num.label)}</div></div>`;
    })
    .join('\n');
  return `<figure class="figure"><figcaption>${inline(caption)}</figcaption>\n${items}\n</figure>`;
}

// Exported for the /research reader, which renders the same document as a web
// page. One renderer means the page and the PDF cannot disagree about a table,
// a figure or a coloured cell.
export function renderBody(md) {
  const blocks = mdToBlocks(md);
  const out = [];
  let listType = null;
  const closeList = () => {
    if (listType) {
      out.push(`</${listType}>`);
      listType = null;
    }
  };
  for (let bi = 0; bi < blocks.length; bi++) {
    const block = blocks[bi];
    const first = block[0];
    const figCaption = block.length === 1 ? FIGURE_CAPTION.exec(first) : null;
    const next = blocks[bi + 1];
    if (figCaption && next && /^\|/.test(next[0])) {
      closeList();
      out.push(renderFigure(figCaption[1], next));
      bi += 1; // the table was consumed by the figure
      continue;
    }
    if (/^#{1,3}\s/.test(first)) {
      closeList();
      const level = first.match(/^(#{1,3})\s/)[1].length;
      const raw = first.replace(/^#{1,3}\s/, '');
      out.push(`<h${level} id="${slug(raw)}">${inline(raw)}</h${level}>`);
    } else if (/^>\s?/.test(first)) {
      closeList();
      const text = block.map((l) => l.replace(/^>\s?/, '')).join(' ');
      out.push(`<blockquote>${inline(text)}</blockquote>`);
    } else if (/^\|/.test(first)) {
      closeList();
      out.push(renderTable(block));
    } else if (/^[-*]\s/.test(first)) {
      if (listType !== 'ul') {
        closeList();
        out.push('<ul>');
        listType = 'ul';
      }
      for (const ln of block) out.push(`<li>${inline(ln.replace(/^[-*]\s/, ''))}</li>`);
    } else if (/^\d+\.\s/.test(first)) {
      if (listType !== 'ol') {
        closeList();
        out.push('<ol>');
        listType = 'ol';
      }
      let cur = '';
      const flush = () => {
        if (cur.trim()) out.push(`<li>${inline(cur.trim())}</li>`);
        cur = '';
      };
      for (const ln of block) {
        if (/^\d+\.\s/.test(ln)) {
          flush();
          cur = ln.replace(/^\d+\.\s/, '');
        } else cur += ' ' + ln;
      }
      flush();
    } else {
      closeList();
      out.push(`<p>${inline(block.join(' '))}</p>`);
    }
  }
  closeList();
  return out;
}

const COLOUR_LEGEND =
  '<p class="legend"><span class="pos">green</span> = saved &ge;20% &middot; ' +
  '<span class="neg">red</span> = cost &ge;20% more &middot; black = within &plusmn;20% = direction-at-best. ' +
  'The &plusmn;20% band is the noise floor this doc demonstrates (cross-session drift ~8pp + N=1 task variance), ' +
  'so within-band magnitudes are not coloured as signal. Colours the &ldquo;% saved&rdquo; columns only; ' +
  'swing/pp and token columns stay neutral.</p>';

/**
 * The document body as one HTML string, legend included when any cell is
 * coloured. Exported for the /research reader; `buildHtml` wraps the same output
 * in the print document. Both go through here so the legend can never appear on
 * one and not the other.
 */
export function renderBodyHtml(md) {
  state.coloured = false;
  const out = renderBody(md);
  if (state.coloured) {
    const h1idx = out.findIndex((b) => b.startsWith('<h1'));
    if (h1idx >= 0) out.splice(h1idx + 1, 0, COLOUR_LEGEND);
    else out.unshift(COLOUR_LEGEND);
  }
  return out.join('\n');
}

export function buildHtml(md, title) {
  const body = renderBodyHtml(md);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${esc(title)}</title>
<style>
  @page { size: A4 landscape; margin: 16mm 14mm; }
  body { font-family: -apple-system, system-ui, "Segoe UI", sans-serif; font-size: 9.5pt; color: #1a1a1a; line-height: 1.45; }
  h1 { font-size: 16pt; margin: 0 0 6pt; }
  h2 { font-size: 12pt; margin: 15pt 0 5pt; border-bottom: 1px solid #ccc; padding-bottom: 2pt; }
  h3 { font-size: 10.5pt; margin: 11pt 0 4pt; }
  p { margin: 5pt 0; }
  ul, ol { margin: 5pt 0; padding-left: 20pt; }
  li { margin: 3pt 0; }
  blockquote { margin: 6pt 0; padding: 4pt 10pt; border-left: 3px solid #ccc; background: #fafafa; color: #333; }
  blockquote p { margin: 0; }
  table { border-collapse: collapse; width: 100%; margin: 6pt 0 12pt; font-size: 8.5pt; page-break-inside: auto; }
  thead { display: table-header-group; }
  tr { page-break-inside: avoid; }
  th, td { border: 1px solid #ddd; padding: 3pt 6pt; vertical-align: top; }
  th { background: #f4f4f4; font-weight: 600; }
  code { font-family: "SF Mono", "Cascadia Code", Consolas, monospace; font-size: 8.5pt; background: #f3f3f3; padding: 0 3px; border-radius: 3px; }
  strong { font-weight: 600; }
  em { font-style: italic; }
  a { color: #0a66c2; text-decoration: none; }
  .pos { color: #1a7f37; }
  .neg { color: #c0392b; }
  td.pos, td.neg { font-weight: 600; }
  .figure { margin: 8pt 0 14pt; padding: 0; page-break-inside: avoid; }
  .figure figcaption { font-size: 8pt; letter-spacing: 0.08em; text-transform: uppercase; color: #666; margin-bottom: 5pt; }
  .figure-row { display: flex; align-items: center; gap: 8pt; margin: 3pt 0; font-size: 8.5pt; }
  .figure-label { flex: 0 0 42%; }
  .figure-track { flex: 1 1 auto; background: #f0f0f0; height: 10pt; border-radius: 2pt; }
  .figure-bar { background: #b45341; height: 10pt; border-radius: 2pt; }
  .figure-value { flex: 0 0 auto; font-weight: 600; min-width: 40pt; text-align: right; }
  .legend { font-size: 8.5pt; color: #555; margin: 0 0 12pt; }
  footer { color: #888; font-size: 8pt; margin-top: 16pt; border-top: 1px solid #eee; padding-top: 4pt; }
</style>
</head>
<body>
${body}
<footer>mikkonumminen.dev &middot; ${esc(title)}</footer>
</body>
</html>
`;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help || !args.input || !args.output) {
    console.log('usage: node scripts/render-audit-doc.mjs --input <md> --output <pdf> [--keep-html]');
    process.exit(args.help ? 0 : 1);
  }
  const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
  const inputAbs = path.resolve(args.input);
  const outputAbs = path.resolve(args.output);
  if (!fs.existsSync(inputAbs)) {
    console.error(`input missing: ${inputAbs}`);
    process.exit(1);
  }
  const md = fs.readFileSync(inputAbs, 'utf8');
  const firstH1 = md.split('\n').find((l) => /^#\s/.test(l));
  const title = firstH1 ? firstH1.replace(/^#\s/, '').trim() : path.basename(inputAbs, '.md');

  const html = buildHtml(md, title);

  const htmlPath = args.keepHtml
    ? outputAbs.replace(/\.pdf$/i, '.html')
    : path.join(os.tmpdir(), `render-audit-doc-${path.basename(outputAbs, '.pdf')}.html`);
  fs.writeFileSync(htmlPath, html);

  printHtmlToPdf({ htmlPath, pdfPath: outputAbs });
  if (!args.keepHtml) fs.rmSync(htmlPath, { force: true });

  console.log(
    `render-audit-doc: ${path.relative(ROOT, inputAbs)} -> ${path.relative(ROOT, outputAbs)}` +
      ` (${tableCountNote(html)}, colour-coded: ${state.coloured})`,
  );
}

function tableCountNote(html) {
  const tables = (html.match(/<table>/g) || []).length;
  return `${tables} table${tables === 1 ? '' : 's'}`;
}

// Run main() only as a CLI (incl. when render-audit-pdfs.mjs spawns this file),
// not when imported by the unit test — so importing inline/pctClass/slug is side-effect-free.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
